mapper.select:
SELECT t1.id, t1.name, t1.category_id, t1.brand_id, t1.pic_url, ( SELECT MIN(retail_price) FROM pms_sku WHERE spu_id = t1.id AND deleted = 0 ) AS price, ( SELECT MIN(market_price) FROM pms_sku WHERE spu_id = t1.id AND deleted = 0 ) AS origin_price, t1.sales, t1.unit, t1.detail, t1.description, t1.spu_type, t1.supplier_id, t5.supplier_name AS supplierName, t3.NAME categoryName, t4.NAME brandName, t1.audit_status, t1.submit_time, t1.audit_time, t1.audit_user, t1.remark, t1.freight_template_id, t1.forbidden_area_id, t1.status, t1.need_delivery FROM pms_spu t1 LEFT JOIN pms_category t3 ON t1.category_id = t3.id LEFT JOIN pms_brand t4 ON t1.brand_id = t4.id LEFT JOIN pms_supplier t5 ON t1.supplier_id = t5.id
and t1.deleted = 0
AND t1.name like concat('%',#{queryParams.keywords},'%')
AND t1.name like concat('%',#{queryParams.name},'%')
AND t1.category_id =#{queryParams.categoryId}
AND t1.brand_id = #{queryParams.brandId}
AND t1.spu_type = #{queryParams.spuType}
AND t1.audit_status = #{queryParams.auditStatus}
AND t1.status = #{queryParams.status}
AND t1.supplier_id = #{queryParams.supplierId}
AND t1.id = #{queryParams.spuId}
AND EXISTS ( SELECT 1 FROM pms_sku sku WHERE sku.spu_id = t1.id AND sku.deleted = 0 AND sku.id = #{queryParams.skuId} )
ORDER BY t1.update_time DESC, t1.create_time DESC

SELECT s.id, s.name, s.pic_url AS picUrl, s.description AS simpleDesc, ( SELECT MIN(retail_price) FROM pms_sku WHERE spu_id = s.id AND deleted = 0 ) AS price, ( SELECT MIN(market_price) FROM pms_sku WHERE spu_id = s.id AND deleted = 0 ) AS originPrice, s.sales, s.spu_type AS spuType, CASE s.spu_type WHEN 'NORMAL' THEN '普通商品' ELSE '普通商品' END AS spuTypeDesc, c3.name AS categoryName, b.name AS brandName, (SELECT MIN(id) FROM pms_sku WHERE spu_id = s.id AND deleted = 0) AS defaultSkuId, (SELECT CASE WHEN COUNT(1) > 1 THEN 1 ELSE 0 END FROM pms_sku WHERE spu_id = s.id AND deleted = 0) AS isExistManySpec FROM `pms_spu` s LEFT JOIN pms_category c3 ON s.category_id = c3.id AND c3.level = 3 LEFT JOIN pms_category c2 ON c3.parent_id = c2.id AND c2.level = 2 LEFT JOIN pms_brand b ON s.brand_id = b.id LEFT JOIN pms_shop sh ON sh.owner_type = 'SUPPLIER' AND sh.owner_id = s.supplier_id AND sh.deleted = 0
AND s.status = 1 AND s.deleted = 0
AND (s.supplier_id IS NULL OR (sh.id IS NOT NULL AND sh.status = 1))
AND s.name like concat('%',#{queryParams.keywords},'%')
AND s.category_id IN ( SELECT c3.id FROM pms_category c3 WHERE c3.level = 3 AND ( c3.id = #{queryParams.categoryId} OR c3.parent_id = #{queryParams.categoryId} OR c3.parent_id IN ( SELECT c2.id FROM pms_category c2 WHERE c2.parent_id = #{queryParams.categoryId} AND c2.level = 2 ) ) )
AND s.brand_id = #{queryParams.brandId}
AND EXISTS ( SELECT 1 FROM pms_sku WHERE spu_id = s.id AND deleted = 0 AND retail_price >= #{queryParams.minPrice} )
AND EXISTS ( SELECT 1 FROM pms_sku WHERE spu_id = s.id AND deleted = 0 AND retail_price <= #{queryParams.maxPrice} )
AND s.spu_type = #{queryParams.spuType}
AND s.spu_type IN
#{type}
AND s.shop_id = #{queryParams.shopId}
AND s.supplier_id = #{queryParams.supplierId}
ORDER BY
${queryParams.sortField} ${queryParams.sort} ,
s.create_time desc

mapper.update:
UPDATE `pms_spu`
SET real_sales = real_sales + #{quantity},
    sales     = sales + #{quantity}
WHERE id = #{spuId}
  and deleted = 0

mapper.select:
SELECT DISTINCT s.brand_id
FROM pms_spu s
WHERE s.status = 1 AND s.deleted = 0 AND s.brand_id IS NOT NULL

    AND s.name LIKE CONCAT('%', #{keywords}, '%')


    AND s.category_id IN (
        SELECT c3.id FROM pms_category c3
        WHERE c3.level = 3
        AND (
            c3.id = #{categoryId}
            OR c3.parent_id = #{categoryId}
            OR c3.parent_id IN (
                SELECT c2.id FROM pms_category c2
                WHERE c2.parent_id = #{categoryId} AND c2.level = 2
            )
        )
    )
